import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"37、【家人】 离下巽上","description":"横渠易说 - 37、【家人】 离下巽上","frontmatter":{"title":"37、【家人】 离下巽上","description":"横渠易说 - 37、【家人】 离下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/039.md","filePath":"zh/classics/hengqu/039.md"}'),l={name:"zh/classics/hengqu/039.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_37、【家人】-离下巽上" tabindex="-1">37、【家人】 离下巽上 <a class="header-anchor" href="#_37、【家人】-离下巽上" aria-label="Permalink to “37、【家人】 离下巽上”">​</a></h1><h3 id="彖曰-家人-女正位乎内-男正位乎外-男女正-天地之大义也。家人有严君焉-父母之谓也。父父-子子-兄兄-弟弟-夫夫-妇妇-而家道正-正家而天下定矣。" tabindex="-1">彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正，正家而天下定矣。 <a class="header-anchor" href="#彖曰-家人-女正位乎内-男正位乎外-男女正-天地之大义也。家人有严君焉-父母之谓也。父父-子子-兄兄-弟弟-夫夫-妇妇-而家道正-正家而天下定矣。" aria-label="Permalink to “彖曰：家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正，正家而天下定矣。”">​</a></h3><h3 id="象曰-风自火出-家人-君子以言有物而行有恒。" tabindex="-1">象曰：风自火出，家人，君子以言有物而行有恒。 <a class="header-anchor" href="#象曰-风自火出-家人-君子以言有物而行有恒。" aria-label="Permalink to “象曰：风自火出，家人，君子以言有物而行有恒。”">​</a></h3><p>家道之始，始诸饮食烹(饫)［饪］，故曰“风自火出”。 家人道在于烹爨，一家之政，乐不乐、平不平皆系乎此。</p><h3 id="初九-闲有家-悔亡。-象曰-闲有家-志未变也。" tabindex="-1">初九，闲有家，悔亡。 象曰：“闲有家”，志未变也。 <a class="header-anchor" href="#初九-闲有家-悔亡。-象曰-闲有家-志未变也。" aria-label="Permalink to “初九，闲有家，悔亡。 象曰：“闲有家”，志未变也。”">​</a></h3><p>男处女下，悔也。</p><h3 id="六二-无攸遂-在中馈-贞吉。-象曰-六二之吉-顺以巽也。" tabindex="-1">六二，无攸遂，在中馈，贞吉。 象曰：六二之吉，顺以巽也。 <a class="header-anchor" href="#六二-无攸遂-在中馈-贞吉。-象曰-六二之吉-顺以巽也。" aria-label="Permalink to “六二，无攸遂，在中馈，贞吉。 象曰：六二之吉，顺以巽也。”">​</a></h3><h3 id="九三-家人嗃嗃-悔厉吉。妇子嘻嘻-终吝。-象曰-家人嗃嗃-未失也-妇子嘻嘻-失家节也。" tabindex="-1">九三，家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。 象曰：“家人嗃嗃”，未失也；“妇子嘻嘻”，失家节也。 <a class="header-anchor" href="#九三-家人嗃嗃-悔厉吉。妇子嘻嘻-终吝。-象曰-家人嗃嗃-未失也-妇子嘻嘻-失家节也。" aria-label="Permalink to “九三，家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。 象曰：“家人嗃嗃”，未失也；“妇子嘻嘻”，失家节也。”">​</a></h3><p>位为过中，则履非得宜，与其慢也宁严。</p><h3 id="六四-富家-大吉。-象曰-富家大吉-顺在位也。" tabindex="-1">六四，富家，大吉。 象曰：“富家大吉”，顺在位也。 <a class="header-anchor" href="#六四-富家-大吉。-象曰-富家大吉-顺在位也。" aria-label="Permalink to “六四，富家，大吉。 象曰：“富家大吉”，顺在位也。”">​</a></h3><p>柔顺在位，故能长保其富。</p><h3 id="九五-王假有家-勿恤-吉。-象曰-王假有家-交相爱也。" tabindex="-1">九五，王假有家，勿恤，吉。 象曰：“王假有家”，交相爱也。 <a class="header-anchor" href="#九五-王假有家-勿恤-吉。-象曰-王假有家-交相爱也。" aria-label="Permalink to “九五，王假有家，勿恤，吉。 象曰：“王假有家”，交相爱也。”">​</a></h3><p>有应在二，得男女内外，家道大正，足以化成天下，故王假之。</p><h3 id="上九-有孚威如-终吉。-象曰-威如之吉-反身之谓也。" tabindex="-1">上九，有孚威如，终吉。 象曰：威如之吉，反身之谓也。 <a class="header-anchor" href="#上九-有孚威如-终吉。-象曰-威如之吉-反身之谓也。" aria-label="Permalink to “上九，有孚威如，终吉。 象曰：威如之吉，反身之谓也。”">​</a></h3><p>以阳居尊，故威如，身修而家齐，故终吉。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
